using Godot;
using System;
using System.Linq;
using System.Collections.Generic;
using Settings=Godot.Collections.Dictionary;
public partial class SceneTabsOperations
{
    public Settings prepare_close(TabBar owner,int index){var documents=Documents(owner);if(index<0||index>=documents.Count)return new Settings();capture_current(owner);var closing=documents[index].AsGodotDictionary();var audio=Workspace(owner,"audio");var session=closing.GetValueOrDefault("state",new Settings()).AsGodotDictionary().GetValueOrDefault("session");bool recording=Kind(closing)=="audio"&&audio!=null&&session.VariantType==Variant.Type.Object&&session.AsGodotObject()!=null&&session.AsGodotObject()==audio.Get("_record_session").AsGodotObject();return new Settings{["closing"]=closing,["recording"]=recording,["session"]=session};}
    public void finish_close(TabBar owner,Settings context,bool discard){var documents=Documents(owner);var closing=context["closing"].AsGodotDictionary();int index=documents.IndexOf(closing);if(index<0)return;if(context.GetValueOrDefault("recording",false).AsBool()&&context["session"].AsGodotObject() is GodotObject session)closing["dirty"]=session.Get("dirty");string kind=Kind(documents[index].AsGodotDictionary());if(!discard&&closing.GetValueOrDefault("dirty",false).AsBool()&&kind is "image" or "audio" or "model" or "environment" or "compositing" or "transformation"){confirm_workspace_close(owner,index,kind);return;}int previous=Active(owner);owner.Set("_switching",true);documents.RemoveAt(index);owner.RemoveTab(index);owner.Set("_switching",false);if(documents.Count==0){add_document(owner,blank_scene(),"",new_untitled_name(owner),new UndoRedo());open_index(owner,0);}else if(index==previous)open_index(owner,Math.Clamp(index,0,documents.Count-1));else{int active=index<previous?previous-1:previous;owner.Set("_active_index",active);owner.Set("_switching",true);owner.CurrentTab=active;owner.Set("_switching",false);refresh_titles(owner);}release_document_history(owner,closing);}
    public void release_document_history(TabBar owner,Settings document){if(Kind(document)=="environment"){var value=document.GetValueOrDefault("state",new Settings()).AsGodotDictionary().GetValueOrDefault("session");var session=value.VariantType==Variant.Type.Object?value.AsGodotObject():null;if(session!=null){session.Get("_undo").AsGodotArray().Clear();session.Get("_redo").AsGodotArray().Clear();}}var historyValue=document.GetValueOrDefault("history");var history=historyValue.VariantType==Variant.Type.Object?historyValue.AsGodotObject() as UndoRedo:null;if(!GodotObject.IsInstanceValid(history))return;var timeline=Timeline(owner);if(GodotObject.IsInstanceValid(timeline)&&timeline!.Get("model").AsGodotObject().Get("history").AsGodotObject()==history)return;foreach(var value in Documents(owner)){var retained=value.AsGodotDictionary().GetValueOrDefault("history");if(retained.VariantType==Variant.Type.Object&&retained.AsGodotObject()==history)return;}history!.ClearHistory();history.Free();}
    public void exit_tree(TabBar owner){var retained=Documents(owner).Duplicate();Documents(owner).Clear();foreach(var value in retained)release_document_history(owner,value.AsGodotDictionary());}
    public void confirm_workspace_close(TabBar owner,int index,string kind)
    {
        var closing=Documents(owner)[index].AsGodotDictionary();if(kind=="image"){var popup=new PopupPanel();popup.AddThemeStyleboxOverride("panel",tab_style(new Color("14212e"),new Color("4a8275")));owner.AddChild(popup);var column=new VBoxContainer{CustomMinimumSize=new Vector2(350,96)};column.AddThemeConstantOverride("separation",8);popup.AddChild(column);var title=new Label{Text="Save your image changes?"};title.AddThemeFontSizeOverride("font_size",19);column.AddChild(title);column.AddChild(new Label{Text=closing["name"].AsString()+" has unsaved edits.",TextOverrunBehavior=TextServer.OverrunBehavior.TrimEllipsis});var row=new HBoxContainer();column.AddChild(row);var cancel=new Button{Text="Keep editing"};row.AddChild(cancel);cancel.Pressed+=popup.Hide;var discard=new Button{Text="Discard"};row.AddChild(discard);discard.Pressed+=()=>{popup.Hide();int current=Documents(owner).IndexOf(closing);if(current>=0)owner.Call("close_scene",current,true);};var save=new Button{Text="Save"};save.AddThemeStyleboxOverride("normal",tab_style(new Color("23594e"),new Color("68d2b6")));row.AddChild(save);save.Pressed+=()=>{popup.Hide();owner.Call("_save_workspace_close_driver",closing,kind);};popup.PopupHide+=popup.QueueFree;popup.PopupCentered(new Vector2I(390,132));return;}if(kind=="audio"){owner.Call("_confirm_audio_close",index);return;}var dialog=new ConfirmationDialog{Title=kind switch{"model"=>"Unsaved model","environment"=>"Unsaved environment","transformation"=>"Unsaved Transformation Image",_=>"Unsaved composition"},DialogText="Save changes to "+closing["name"].AsString()+"?",OkButtonText="Save",CancelButtonText="Keep editing"};owner.AddChild(dialog);var discardButton=dialog.AddButton("Discard",kind is "environment" or "compositing","discard");discardButton.Pressed+=()=>{dialog.QueueFree();int current=Documents(owner).IndexOf(closing);if(current>=0)owner.Call("close_scene",current,true);};dialog.Confirmed+=()=>{dialog.QueueFree();owner.Call("_save_workspace_close_driver",closing,kind);};dialog.Canceled+=dialog.QueueFree;dialog.PopupCentered(kind=="environment"?new Vector2I(360,150):kind=="transformation"?new Vector2I(410,140):new Vector2I(390,150));
    }
    public Settings prepare_workspace_close_save(TabBar owner,Settings closing,string kind){capture_current(owner);int index=Documents(owner).IndexOf(closing);if(index<0)return new Settings();open_index(owner,index);var workspace=Workspace(owner,kind);if(workspace==null)return new Settings();Variant session=kind is "model" or "environment" or "transformation"?workspace.Get("session"):default;if(kind=="compositing"){var document=workspace.Get("document").As<Resource>();var callback=Callable.From<string,Resource>((_,saved)=>{if(!GodotObject.IsInstanceValid(owner)||!GodotObject.IsInstanceValid(workspace)||saved!=document)return;int at=Documents(owner).IndexOf(closing);if(at>=0&&!workspace.Get("dirty").AsBool())owner.Call("close_scene",at,true);});workspace.Connect("composition_saved",callback,(uint)GodotObject.ConnectFlags.OneShot);workspace.Call("save");return new Settings();}return new Settings{["session"]=session,["kind"]=kind,["closing"]=closing};}
    public void finish_workspace_close_save(TabBar owner,Settings context){var closing=context["closing"].AsGodotDictionary();int index=Documents(owner).IndexOf(closing);if(index<0)return;string kind=context["kind"].AsString();var workspace=Workspace(owner,kind);if(workspace==null)return;bool dirty=kind=="image"?workspace.Get("_dirty").AsBool():context["session"].AsGodotObject().Get("dirty").AsBool();if(!dirty&&(kind!="environment"||workspace.Get("path").AsString().Length>0))owner.Call("close_scene",index,true);}
    public StyleBoxFlat tab_style(Color background,Color border){var style=new StyleBoxFlat{BgColor=background,BorderColor=border,ContentMarginLeft=12,ContentMarginRight=12,ContentMarginTop=5,ContentMarginBottom=5};style.SetBorderWidthAll(1);style.SetCornerRadiusAll(6);return style;}
}
